		o.put("addressLine1", seq() + " Test Street");
		o.put("postcode", "2000");
		return o;
	}

	// --- requests -----------------------------------------------------------

	protected String json(JsonNode node) {
		try {
			return om.writeValueAsString(node);
		}
		catch (Exception e) {
			throw new RuntimeException(e);
		}
	}

	protected ResultActions createOwner(JsonNode body) throws Exception {
