69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
77	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
78	
79	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
80	    private static final int MAX_OWNERS_PER_CITY = 50;
81	
82	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
83	    private static final int MAX_OWNERS_PER_DAY = 100;
84	
85	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
86	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
87	
88	    /** Fixed public holidays the business-day roll skips: the adjusted registration date never lands on one of these. */
89	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
90	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
91	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
92	
93	    private final ClinicService clinicService;
94	
95	    private final OwnerMapper ownerMapper;
96	
97	    private final PetMapper petMapper;
98	
99	    private final VisitMapper visitMapper;
100	
101	    private final TelephoneNormalizer telephoneNormalizer;
102	
103	    private final AddressNormalizer addressNormalizer;
104	
105	    private final EmailNormalizer emailNormalizer;
106	
107	    private final IdentityKeyResolver identityKeyResolver;
108	
109	    private final HouseholdResolver householdResolver;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 TelephoneNormalizer telephoneNormalizer,
116	                                 AddressNormalizer addressNormalizer,
117	                                 EmailNormalizer emailNormalizer,
118	                                 IdentityKeyResolver identityKeyResolver,
119	                                 HouseholdResolver householdResolver) {
120	        this.clinicService = clinicService;
121	        this.ownerMapper = ownerMapper;
122	        this.petMapper = petMapper;
123	        this.visitMapper = visitMapper;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.addressNormalizer = addressNormalizer;
126	        this.emailNormalizer = emailNormalizer;
127	        this.identityKeyResolver = identityKeyResolver;
128	        this.householdResolver = householdResolver;
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
134	        Collection<Owner> owners;
135	        if (lastName != null) {
136	            owners = this.clinicService.findOwnerByLastName(lastName);
137	        } else {
138	            owners = this.clinicService.findAllOwners();
139	        }
140	        if (owners.isEmpty()) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        owners.forEach(this::populateHouseholdMemberCount);
144	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
145	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        populateHouseholdMemberCount(owner);
156	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
157	    }
158	
159	    /**
160	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
161	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
162	     * by the mapper alone.
163	     *
164	     * @param owner the owner to map
165	     * @return the owner DTO carrying its identity key
166	     */
167	    private OwnerDto toOwnerDto(Owner owner) {
168	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
169	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
170	        return ownerDto;
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Transactional
175	    @Override
176	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
177	        Owner owner = createOwner(ownerFieldsDto);
178	        return createdOwnerResponse(owner);
179	    }
180	
181	    /**
182	     * Creates and persists a new owner from an incoming payload, applying every creation rule in order. The payload is
183	     * normalized and validated (see {@link #normalizeAndValidate}), mapped to an owner and stamped with its fields
184	     * derived at creation (see {@link #populateDerivedFields}); the duplicate guards then run against those derived
185	     * fields (see {@link #requireUniqueIdentity} and {@link #requireHouseholdNotDuplicate}) before the soft-duplicate
186	     * flag is recorded (see {@link #flagPossibleDuplicate}); the owner is saved, its transient household member count
187	     * is resolved (see {@link #populateHouseholdMemberCount}) and the creation is audited (see
188	     * {@link #auditOwnerCreated}). The returned owner carries its generated id and every field a response needs.
189	     *
190	     * @param ownerFieldsDto the incoming owner payload, mutated in place during normalization
191	     * @return the newly created, persisted owner
192	     */
193	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
194	        normalizeAndValidate(ownerFieldsDto);
195	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
196	        populateDerivedFields(owner, ownerFieldsDto);
197	        requireUniqueIdentity(owner);
198	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
199	        flagPossibleDuplicate(owner, ownerFieldsDto);
200	        this.clinicService.saveOwner(owner);
201	        populateHouseholdMemberCount(owner);
202	        auditOwnerCreated(owner);
203	        return owner;
204	    }
205	
206	    /**
207	     * Builds the {@code 201 Created} response for a newly created owner: the owner mapped to its DTO (carrying its
208	     * identity key, see {@link #toOwnerDto}) as the body, with a {@code Location} header pointing at the new owner's
209	     * canonical URL.
210	     *
211	     * @param owner the newly created, persisted owner
212	     * @return a {@code 201 Created} response carrying the owner DTO and its {@code Location} header
213	     */
214	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
215	        OwnerDto ownerDto = toOwnerDto(owner);
216	        HttpHeaders headers = new HttpHeaders();
217	        headers.setLocation(UriComponentsBuilder.newInstance()
218	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
219	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
220	    }
221	
222	    /**
223	     * Emits the single audit line for a successfully created owner to the dedicated {@link #AUDIT} logger, recording
224	     * its id, customer code and registration date alongside the two values derived purely for the audit trail: the
225	     * membership level (see {@link MembershipLevelResolver#deriveMembershipLevel}) and the membership number, the
226	     * customer code suffixed with {@code -M} and the two-digit fiscal year of the registration date (see
227	     * {@link FiscalYearResolver#fiscalYear}).
228	     *
229	     * @param owner the newly created, persisted owner, with all its derived fields already in place
230	     */
231	    private void auditOwnerCreated(Owner owner) {
232	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
233	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
234	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount(),
235	                owner.getHouseholdMemberCount(), owner.getRegistrationDate()),
236	            owner.getCustomerCode() + "-M" + String.format("%02d",
237	                FiscalYearResolver.fiscalYear(owner.getRegistrationDate()) % 100));
238	    }
239	
240	    /**
241	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
242	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
243	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
244	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
245	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
246	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
247	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
248	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
249	     *
250	     * @param owner          the newly mapped owner about to be saved
251	     * @param ownerFieldsDto the incoming owner payload
252	     */
253	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
254	        owner.setCustomerCode(deriveUniqueCustomerCode(owner));
255	        owner.setNamesakeCount(countNamesakes(owner));
256	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
257	        assignHouseholdId(owner);
258	    }
259	
260	    /**
261	     * Derives an owner's {@code customerCode} and de-duplicates it against the owners that already exist. The base code
262	     * is the pure derivation (see {@link IdentityKeyResolver#deriveCustomerCode}); when it collides with an existing
263	     * owner's {@code customerCode} it is suffixed with {@code -<n>}, taking the smallest {@code n} of 2 or more that
264	     * makes the whole code unique. Evaluated before the new owner is saved, so the collision check reflects only owners
265	     * that predate this create; distinct owners therefore always receive distinct customer codes.
266	     *
267	     * @param owner the newly mapped owner about to be saved, with its telephone already normalized
268	     * @return the de-duplicated customer code, unique across all existing owners
269	     */
270	    private String deriveUniqueCustomerCode(Owner owner) {
271	        String base = identityKeyResolver.deriveCustomerCode(owner);
272	        Collection<Owner> existing = this.clinicService.findAllOwners();
273	        String candidate = base;
274	        int n = 2;
275	        while (isCustomerCodeInUse(candidate, existing)) {
276	            candidate = base + "-" + n;
277	            n++;
278	        }
279	        return candidate;
280	    }
281	
282	    private boolean isCustomerCodeInUse(String customerCode, Collection<Owner> existing) {
283	        return existing.stream().anyMatch(other -> customerCode.equals(other.getCustomerCode()));
284	    }
285	
286	    /**
287	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
288	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
289	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
290	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
291	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
292	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
293	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
294	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
295	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
296	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
297	     * assigned (see {@link #requireUniqueIdentity}).
298	     *
299	     * @param ownerFieldsDto the incoming owner payload, mutated in place
300	     * @throws MissingOwnerFieldsException if any required field is missing or blank
301	     */
302	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
303	        normalizeAddress(ownerFieldsDto);
304	        validateRequiredFields(ownerFieldsDto);
305	        validatePostcode(ownerFieldsDto);
306	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
307	        ownerFieldsDto.setTelephone(telephone);
308	        requireCityHasCapacity(ownerFieldsDto.getCity());
309	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
310	        ownerFieldsDto.setRegistrationDate(registrationDate);
311	        requireDailyLimitNotReached(registrationDate);
312	        normalizeEmail(ownerFieldsDto);
313	    }
314	
315	    /**
316	     * Normalizes an owner's address to its canonical stored form and writes it back onto the payload. The structured
317	     * form is preferred over the flat one: when a non-blank {@code addressLine1} is supplied it (and the optional
318	     * {@code addressLine2}) are normalized (see {@link AddressNormalizer#normalize}) and the flat {@code address} is
319	     * recomposed as the normalized {@code addressLine1}, with a single space and the normalized {@code addressLine2}
320	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized on its own and the
321	     * structured fields are cleared. Either way the canonical {@code address} is what gets stored and returned and what
322	     * every downstream reader uses; a blank result is uniformly treated as a missing address by the required-field
323	     * check that follows (an owner is valid when it supplies either a non-blank {@code addressLine1} or a non-blank flat
324	     * {@code address}). The payload is mutated in place so the caller can map and save it directly.
325	     *
326	     * @param ownerFieldsDto the incoming owner payload, mutated in place
327	     */
328	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
329	        String line1 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
330	        String line2 = addressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
331	        if (!line1.isEmpty()) {
332	            ownerFieldsDto.setAddressLine1(line1);
333	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
334	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
335	        }
336	        else {
337	            ownerFieldsDto.setAddressLine1(null);
338	            ownerFieldsDto.setAddressLine2(null);
339	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
340	        }
341	    }
342	
343	    /**
344	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
345	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
346	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
347	     * place so the caller can map and save it directly.
348	     *
349	     * @param ownerFieldsDto the incoming owner payload, mutated in place
350	     */
351	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
352	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
353	    }
354	
355	    /**
356	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
357	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday, a Sunday
358	     * or a listed public holiday (see {@link #PUBLIC_HOLIDAYS}) it is rolled forward one day at a time until it lands on
359	     * a non-holiday weekday. The returned date is always a business day. A supplied date later than the current server
360	     * date is rejected.
361	     *
362	     * @param ownerFieldsDto the incoming owner payload
363	     * @return the effective registration date rolled forward onto a business day
364	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
365	     */
366	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
367	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
368	        if (effective == null) {
369	            effective = LocalDate.now();
370	        }
371	        else if (effective.isAfter(LocalDate.now())) {
372	            throw new FutureRegistrationDateException(
373	                "the registration date must not be later than the current server date");
374	        }
375	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY
376	            || PUBLIC_HOLIDAYS.contains(effective)) {
377	            effective = effective.plusDays(1);
378	        }
379	        return effective;
380	    }
381	
382	    /**
383	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
384	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
385	     * further owner may be created for that day.
386	     *
387	     * @param registrationDate the adjusted business-day registration date of the owner being created
388	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
389	     */
390	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
391	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
392	            throw new DailyOwnerLimitExceededException(
393	                "the maximum number of owners for today has already been reached");
394	        }
395	    }
396	
397	    /**
398	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
399	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
400	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
401	     * warning threshold) so both express the same per-day count in one place.
402	     *
403	     * @param registrationDate the adjusted business-day registration date to count owners for
404	     * @return the number of existing owners registered on that day
405	     */
406	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
407	        return this.clinicService.findAllOwners().stream()
408	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
409	            .count();
410	    }
411	
412	    /**
413	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
414	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
415	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
416	     * reflects only owners that predate it.
417	     *
418	     * @param registrationDate the adjusted business-day registration date of the owner being created
419	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
420	     */
421	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
422	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
423	    }
424	
425	    /**
426	     * Counts how many existing owners already share the given owner's first and last name, compared
427	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
428	     * create; it is zero when the owner's name is unique.
429	     *
430	     * @param owner the newly mapped owner about to be saved
431	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
432	     */
433	    private int countNamesakes(Owner owner) {
434	        String firstName = owner.getFirstName();
435	        String lastName = owner.getLastName();
436	        return (int) this.clinicService.findAllOwners().stream()
437	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
438	                && lastName.equalsIgnoreCase(existing.getLastName()))
439	            .count();
440	    }
441	
442	    /**
443	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
444	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
445	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
446	     *
447	     * <p>The address is checked after normalization has composed the canonical {@code address} from whichever form was
448	     * supplied, so a blank {@code address} here means the owner supplied neither a non-blank {@code addressLine1} nor a
449	     * flat {@code address}.
450	     *
451	     * @param ownerFieldsDto the owner payload to validate
452	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
453	     */
454	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
455	        List<String> missingFields = new ArrayList<>();
456	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
457	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
458	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
459	        requireText(missingFields, "city", ownerFieldsDto.getCity());
460	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
461	        if (!missingFields.isEmpty()) {
462	            throw new MissingOwnerFieldsException(missingFields);
463	        }
464	    }
465	
466	    private void requireText(List<String> missingFields, String fieldName, String value) {
467	        if (value == null || value.isBlank()) {
468	            missingFields.add(fieldName);
469	        }
470	    }
471	
472	    /**
473	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
474	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
475	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
476	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
477	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
478	     *
479	     * @param ownerFieldsDto the incoming owner payload
480	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
481	     */
482	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
483	        String postcode = ownerFieldsDto.getPostcode();
484	        if (postcode == null) {
485	            return;
486	        }
487	        Region region = Region.forCity(ownerFieldsDto.getCity());
488	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
489	            throw new InvalidPostcodeException(
490	                "postcode " + postcode + " is not valid for the city's region " + region.name());
491	        }
492	    }
493	
494	    /**
495	     * Rejects creating an owner whose whole derived {@code identityKey} (see
496	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
497	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
498	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
499	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
500	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}). Owners that have been
501	     * soft-deleted (see {@link #deleteOwner}) are ignored, so a matching identity that belongs only to a deleted
502	     * owner does not block the create.
503	     *
504	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
505	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
506	     */
507	    private void requireUniqueIdentity(Owner owner) {
508	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
509	        boolean inUse = this.clinicService.findAllOwners().stream()
510	            .filter(existing -> !existing.isDeleted())
511	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
512	        if (inUse) {
513	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
514	        }
515	    }
516	
517	    /**
518	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
519	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
520	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
521	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
522	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
523	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
524	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
525	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
526	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
527	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
528	     *
529	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
530	     * @param ownerFieldsDto the incoming owner payload
531	     */
532	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
533	        owner.setPossibleDuplicate(false);
534	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
535	            return;
536	        }
537	        String postcode = owner.getPostcode();
538	        if (postcode == null || postcode.isBlank()) {
539	            return;
540	        }
541	        String lastName = owner.getLastName();
542	        String telephone = owner.getTelephone();
543	        for (Owner existing : this.clinicService.findAllOwners()) {
544	            if (lastName.equalsIgnoreCase(existing.getLastName())
545	                && postcode.equals(existing.getPostcode())
546	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
547	                owner.setPossibleDuplicate(true);
548	                owner.setPossibleDuplicateOf(existing.getId());
549	                return;
550	            }
551	        }
552	    }
553	
554	    /**
555	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
556	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
557	     *
558	     * @param city the city of the owner being created
559	     * @throws OwnerCityFullException if the city already contains 50 or more owners
560	     */
561	    private void requireCityHasCapacity(String city) {
562	        long cityOwners = this.clinicService.findAllOwners().stream()
563	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
564	            .count();
565	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
566	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
567	        }
568	    }
569	
570	    /**
571	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
572	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
573	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
574	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
575	     * such owners never match one another as a household.
576	     *
577	     * @param owner the newly mapped owner about to be saved
578	     */
579	    private void assignHouseholdId(Owner owner) {
580	        String postcode = owner.getPostcode();
581	        if (postcode == null || postcode.isBlank()) {
582	            owner.setHouseholdId(null);
583	            return;
584	        }
585	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
586	    }
587	
588	    /**
589	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
590	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
591	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
592	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
593	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
594	     * without a postcode) can never be a household duplicate. Owners that have been soft-deleted (see
595	     * {@link #deleteOwner}) are ignored, so a household whose only member has been deleted does not block the create.
596	     *
597	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
598	     * @param ownerFieldsDto the incoming owner payload
599	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
600	     *                                 declare {@code sharesHousehold}
601	     */
602	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
603	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
604	            return;
605	        }
606	        String householdId = owner.getHouseholdId();
607	        if (householdId == null) {
608	            return;
609	        }
610	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
611	            .filter(existing -> !existing.isDeleted())
612	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
613	        if (sharedByExisting) {
614	            throw new DuplicateOwnerException("an owner in the same household already exists");
615	        }
616	    }
617	
618	    /**
619	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
620	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
621	     * household is counted as a household of one.
622	     *
623	     * @param owner the owner whose household size should be resolved
624	     */
625	    private void populateHouseholdMemberCount(Owner owner) {
626	        String householdId = owner.getHouseholdId();
627	        if (householdId == null) {
628	            owner.setHouseholdMemberCount(1);
629	            return;
630	        }
631	        long members = this.clinicService.findAllOwners().stream()
632	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
633	            .count();
634	        owner.setHouseholdMemberCount((int) members);
635	    }
636	
637	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
638	    @Override
639	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
640	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
641	        if (currentOwner == null) {
642	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
643	        }
644	        validatePostcode(ownerFieldsDto);
645	        currentOwner.setAddress(ownerFieldsDto.getAddress());
646	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
647	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
648	        currentOwner.setCity(ownerFieldsDto.getCity());
649	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
650	        currentOwner.setLastName(ownerFieldsDto.getLastName());
651	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
652	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
653	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
654	        this.clinicService.saveOwner(currentOwner);
655	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
656	    }
657	
658	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
659	    @Transactional
660	    @Override
661	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
662	        Owner owner = this.clinicService.findOwnerById(ownerId);
663	        if (owner == null) {
664	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
665	        }
666	        owner.setDeleted(true);
667	        this.clinicService.saveOwner(owner);
668	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
669	    }
670	
671	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
672	    @Override
673	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
674	        Owner owner = this.clinicService.findOwnerById(ownerId);
675	        if (owner == null) {
676	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
677	        }
678	        HttpHeaders headers = new HttpHeaders();
679	        Pet pet = petMapper.toPet(petFieldsDto);
680	        owner.setId(ownerId);
681	        pet.setOwner(owner);
682	        pet.getType().setName(null);
683	        this.clinicService.savePet(pet);
684	        PetDto petDto = petMapper.toPetDto(pet);
685	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
686	            .buildAndExpand(pet.getId()).toUri());
687	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
688	    }
689	
690	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
691	    @Override
692	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
693	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
694	        if (currentOwner != null) {
695	            Pet currentPet = this.clinicService.findPetById(petId);
696	            if (currentPet != null) {
697	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
698	                currentPet.setName(petFieldsDto.getName());
699	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
700	                this.clinicService.savePet(currentPet);
701	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
702	            }
703	        }
704	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
705	    }
706	
707	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
708	    @Override
709	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
710	        HttpHeaders headers = new HttpHeaders();
711	        Visit visit = visitMapper.toVisit(visitFieldsDto);
712	        Pet pet = new Pet();
713	        pet.setId(petId);
714	        visit.setPet(pet);
715	        this.clinicService.saveVisit(visit);
716	        VisitDto visitDto = visitMapper.toVisitDto(visit);
717	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
718	            .buildAndExpand(visit.getId()).toUri());
719	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
720	    }
721	
722	
723	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
724	    @Override
725	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
726	        Owner owner = this.clinicService.findOwnerById(ownerId);
727	        if (owner != null) {
728	            Pet pet = owner.getPet(petId);
729	            if (pet != null) {
730	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
731	            }
732	        }
733	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
734	    }
735	}
